```dart
List<double> rescaleToUnit(List<double> numbers) {
  if (numbers.isEmpty) return [];

  double min = numbers.reduce((a, b) => a < b ? a : b);
  double max = numbers.reduce((a, b) => a > b ? a : b);

  // Avoid division by zero in case all elements are the same.
  final rangeSize = max - min;

  List<double> scaledNumbers = [];
  for (var num in numbers) {
    var ratio = (num - min) / rangeSize; 
    scaledNumbers.add(ratio.clamp(0.0, 1.0)); // Clamp to [0..1]
  }

  return scaledNumbers;
